# roffsub.fn.bash --- check, compile, and render terminal manuals written in roffsub
# roffsub r0.9
# (c) 2026 George Georgalis <george@iuxta.com> Unlimited use with attribution.
#
# Source this file to define the roffsub function.  It behaves as the
# roffsub binary does, for systems where programs cannot be run from the
# user's own directories (a home mounted noexec).  The regions between
# "# roffsub NAME begin" and "# roffsub NAME end" are generated by
# "make fn" from the awk tools and the roffsub(1) manual; do not edit them.

roffsub ()
{
	local _rs_check _rs_ir _rs_render _rs_emit _rs_gen _rs_page _rs_man
	local _rs_mode=render _rs_w= _rs_s= _rs_m= _rs_date= _rs_rev=
	local _rs_lang= _rs_name= _rs_in= _rs_W=80 _rs_S=plain _rs_pg=
	local _rs_sb=1 _rs_si=4 _rs_meas=0 _rs_head=0 _rs_x= _rs_cmd= _rs_usage

# roffsub _rs_check begin (generated by roffsub-gen.awk; do not edit)
IFS= read -r -d '' _rs_check <<'__ROFFSUB__rs_check__' || :
# roffsub-check.awk --- check that a source follows the roffsub form
# roffsub r0.9
# (c) 2026 George Georgalis <george@iuxta.com> Unlimited use with attribution.
#
# usage: LC_ALL=C awk [-v strict=1] -f roffsub-check.awk FILE.1 ...
#
# Reports FILE:LINE: ID: message on stderr.  Exit status 1 when any
# error was found (or any warning, with strict=1).  Form only; content
# is not judged.
#
#   E01 byte outside 0x20-0x7E      E07 '\" t line and tables disagree
#   E02 request not in roffsub      E08 table form
#   E03 escape not in roffsub       E09 .TH missing or not first
#   E04 unbalanced pair             E10 request arguments
#   E05 fill-mode text line form    E11 .TP without a tag line
#   E06 font not roman at a boundary
#   W01 option hyphen without \-    W02 abbreviation ends a line
#   W03 table too wide for roff at 80 columns (roff wraps only T{ T} cells)

BEGIN {
	REQ = "^(TH|SH|SS|PP|P|LP|TP|IP|RS|RE|nf|fi|B|I|BR|RB|IR|RI|BI|IB|sp|br|TS|TE)$"
	FONTREQ = "^(B|I|BR|RB|IR|RI|BI|IB)$"
	errs = 0; warns = 0
}

function report(id, msg) {
	printf "%s:%d: %s: %s\n", FILENAME, FNR, id, msg > "/dev/stderr"
	if (id ~ /^E/) errs++; else warns++
}

function reset() {
	tflag = 0; hastable = 0; seenreq = 0; seenth = 0
	nf = 0; rs = 0; intable = 0; inblock = 0; tpwait = 0; font = "R"
}

# check escapes in s; track font; return 0 on error
function escapes(s,    i, c, d, x, ok) {
	ok = 1
	for (i = 1; i <= length(s); i++) {
		if (substr(s, i, 1) != "\\") continue
		d = substr(s, i + 1, 1)
		if (d == "f") {
			x = substr(s, i + 2, 1)
			if (x ~ /^[BIRP]$/) { if (x == "P") x = pfont; pfont = font; font = x }
			else { report("E03", "font escape \\f" x " not in roffsub"); ok = 0 }
			i += 2
		} else if (d == "(") {
			x = substr(s, i + 2, 2)
			if (x !~ /^(em|en|bu|aq|dq)$/) { report("E03", "character \\(" x " not in roffsub"); ok = 0 }
			i += 3
		} else if (d ~ /^[-e& ]$/) i++
		else if (d == "") { report("E03", "backslash at end of line"); ok = 0 }
		else { report("E03", "escape \\" d " not in roffsub"); ok = 0; i++ }
	}
	return ok
}

function args(s, a,    n, i, c, cur, inq, have) {
	split("", a); n = 0; cur = ""; inq = 0; have = 0
	for (i = 1; i <= length(s); i++) {
		c = substr(s, i, 1)
		if (c == "\\") { cur = cur substr(s, i, 2); i++; have = 1; continue }
		if (c == "\"") {
			if (inq && substr(s, i + 1, 1) == "\"") report("E10", "embedded \"\" (write \\(dq)")
			inq = !inq; have = 1; continue
		}
		if (c == " " && !inq) { if (have) { a[++n] = cur; cur = ""; have = 0 }; continue }
		cur = cur c; have = 1
	}
	if (have) a[++n] = cur
	return n
}

function isw(w) { return w ~ /^[0-9]+n?$/ }

function optwarn(s,    t) {
	t = " " s
	gsub(/\\-/, "", t)
	if (t ~ /[ [(|]-[A-Za-z]/) report("W01", "option hyphen written without \\-")
}

# visible width of a cell, escapes resolved roughly
function vis(s,    t) {
	t = s
	gsub(/\\f[BIRP]/, "", t); gsub(/\\\([a-z][a-z]/, "x", t); gsub(/\\&/, "", t); gsub(/\\./, "x", t)
	return length(t)
}

function cell(s, blk) {
	if (!blk && vis(s) > cw[ncell]) cw[ncell] = vis(s)
	pfont = "R"; font = "R"
	escapes(s)
	if (font != "R") report("E06", "font not roman at end of table cell")
	font = "R"
}

function row(s,    p, piece) {
	while (1) {
		p = index(s, tabc)
		piece = p ? substr(s, 1, p - 1) : s
		if (!p && piece == "T{") { inblock = 1; block = ""; return }
		ncell++; cell(piece)
		if (!p) break
		s = substr(s, p + 1)
	}
	endrow()
}

function endrow() {
	if (ncell != ncol) report("E08", "row has " ncell " cells, format has " ncol)
	ncell = 0
}

function finish() {
	if (FNAME == "") return
	if (nf) report("E04", ".nf without .fi")
	if (rs) report("E04", ".RS without .RE")
	if (intable) report("E04", ".TS without .TE")
	if (tpwait) report("E11", ".TP at end of file without a tag line")
	if (!seenth) report("E09", ".TH missing")
	if (hastable && !tflag) report("E07", "table present but line 1 is not '\\\" t")
	if (tflag && !hastable) report("E07", "line 1 is '\\\" t but no table present")
}

FNR == 1 { finish(); FNAME = FILENAME; reset() }

/[^ -~]/ { report("E01", "byte outside printable ASCII (TAB, CR, or non-ASCII)") }

FNR == 1 && $0 == "'\\\" t" { tflag = 1; next }

intable {
	if (inblock) {
		if (substr($0, 1, 2) == "T}") {
			inblock = 0; ncell++; cell(block, 1)
			rest = substr($0, 3)
			if (rest == "") endrow()
			else if (substr(rest, 1, 1) != tabc) report("E08", "text after T} must begin with the tab character")
			else row(substr(rest, 2))
		} else {
			if ($0 ~ /^\./) report("E08", "request inside a text block")
			block = block " " $0
		}
		next
	}
	if ($0 == ".TE") {
		intable = 0; w = 3 * (ncol - 1)
		for (i = 1; i <= ncol; i++) w += cw[i]
		if (w > 71) report("W03", "table is " w " columns wide; roff wraps only T{ T} cells, so make the wide cells text blocks")
		next
	}
	if (tstate == "opts") {
		if ($0 !~ /;[ ]*$/) report("E08", "table options line must end with ;")
		if (match($0, /tab\(.\)/)) {
			tabc = substr($0, RSTART + 4, 1)
			if (tabc ~ /[A-Za-z0-9 ]/) report("E08", "tab character must be printable and not alphanumeric")
		} else { report("E08", "table options line needs tab(c)"); tabc = "\t" }
		line = $0; sub(/tab\(.\)/, "", line); sub(/;[ ]*$/, "", line)
		n = split(line, o, " ")
		for (i = 1; i <= n; i++)
			if (o[i] !~ /^(box|allbox|center)$/) report("E08", "table option " o[i] " not in roffsub")
		tstate = "fmt"; ncol = 0; split("", cw); next
	}
	if (tstate == "fmt") {
		line = $0; last = (line ~ /\.[ ]*$/); sub(/\.[ ]*$/, "", line)
		n = split(line, k, " ")
		if (ncol && n != ncol) report("E08", "format lines differ in column count")
		ncol = n
		for (i = 1; i <= n; i++) {
			x = k[i]; gsub(/w\([0-9]+n?\)/, "", x)
			if (x !~ /^[bi]*[lrc][bi]*$/) report("E08", "format key " k[i] " not in roffsub")
		}
		if (last) tstate = "data"
		next
	}
	if ($0 == "_") next
	if ($0 ~ /^\./) { report("E08", "request inside a table"); next }
	ncell = 0; row($0)
	next
}

/^\.\\"/ { next }

/^'/ { report("E02", "' as a control character"); next }

/^\./ {
	name = $0; sub(/^\./, "", name); sub(/ .*/, "", name)
	rest = substr($0, length(name) + 2); sub(/^ +/, "", rest)
	if (name !~ REQ) { report("E02", "request ." name " not in roffsub"); next }
	if (font != "R") report("E06", "font not roman before ." name)
	if (tpwait && name !~ FONTREQ) report("E11", ".TP followed by ." name ", not a tag line")
	tpwait = 0
	if (!seenreq && name != "TH") report("E09", ".TH must be the first request")
	seenreq = 1
	n = args(rest, a)
	if (n > 9) report("E10", "more than 9 arguments")
	pfont = "R"; font = "R"
	escapes(rest)
	if (font != "R") report("E06", "font not roman at end of ." name " line")
	font = "R"
	if (name == "TH") { seenth = 1; if (n < 2) report("E10", ".TH needs at least NAME and SEC") }
	else if (name ~ /^(SH|SS)$/) {
		if (!n) report("E10", "." name " needs its heading as an argument")
		if (nf) report("E04", "." name " inside .nf")
		if (rs) { report("E04", ".RS not closed before ." name); rs = 0 }
		if (name == "SH") inss = 0
	}
	else if (name == "TP") { if (n > 1 || (n && !isw(a[1]))) report("E10", ".TP takes an optional width in n"); tpwait = 1 }
	else if (name == "IP") { if (n > 2 || (n == 2 && !isw(a[2]))) report("E10", ".IP takes [tag [width]]") }
	else if (name == "RS") { if (n > 1 || (n && !isw(a[1]))) report("E10", ".RS takes an optional width in n"); rs++ }
	else if (name == "RE") { if (!rs) report("E04", ".RE without .RS"); else rs--; if (n) report("E10", ".RE takes no argument") }
	else if (name == "nf") { if (nf) report("E04", ".nf inside .nf"); nf = 1 }
	else if (name == "fi") { if (!nf) report("E04", ".fi without .nf"); nf = 0 }
	else if (name == "sp") { if (n > 1 || (n && a[1] !~ /^[0-9]+$/)) report("E10", ".sp takes an optional line count") }
	else if (name ~ /^(PP|P|LP|br)$/) { if (n) report("E10", "." name " takes no argument") }
	else if (name == "TS") {
		if (nf) report("E04", ".TS inside .nf")
		intable = 1; hastable = 1; tstate = "opts"
	}
	else if (name == "TE") report("E04", ".TE without .TS")
	else if (name ~ FONTREQ) { if (!n) report("E10", "." name " needs its words as arguments"); optwarn(rest) }
	next
}

{
	if (tpwait) tpwait = 0
	if (!nf) {
		if ($0 == "") report("E05", "empty line in fill mode (use .PP or .sp)")
		else if ($0 ~ /^ /) report("E05", "text line begins with a space in fill mode")
		if ($0 ~ /(e\.g\.|i\.e\.|etc\.|vs\.)$/) report("W02", "abbreviation ends the line; add \\&")
	}
	escapes($0)
	optwarn($0)
}

END {
	finish()
	exit (errs || (strict && warns)) ? 1 : 0
}
__ROFFSUB__rs_check__
# roffsub _rs_check end
# roffsub _rs_ir begin (generated by roffsub-gen.awk; do not edit)
IFS= read -r -d '' _rs_ir <<'__ROFFSUB__rs_ir__' || :
# roffsub-ir.awk --- compile a roffsub source into records
# roffsub r0.9
# (c) 2026 George Georgalis <george@iuxta.com> Unlimited use with attribution.
#
# usage: awk [-v date=DATE] [-v version=VERSION] -f roffsub-ir.awk FILE.1
#
# Output: one record per line, an operation name then TAB-separated
# fields.  Text fields carry only \fB \fI \fR \\ \~ and end in roman.
# The source is assumed to pass roffsub-check.awk.

BEGIN {
	TAB = "\t"
	font = "R"; prev = "R"; carry = ""
	nf = 0; tpwait = 0; intable = 0; inblock = 0
	print "v" TAB "1"
}

# argument splitting: double quotes group, backslash pairs never split
function args(s, a,    n, i, c, cur, inq, have) {
	split("", a)
	n = 0; cur = ""; inq = 0; have = 0
	for (i = 1; i <= length(s); i++) {
		c = substr(s, i, 1)
		if (c == "\\") { cur = cur substr(s, i, 2); i++; have = 1; continue }
		if (c == "\"") { inq = !inq; have = 1; continue }
		if (c == " " && !inq) {
			if (have) { a[++n] = cur; cur = ""; have = 0 }
			continue
		}
		cur = cur c; have = 1
	}
	if (have) a[++n] = cur
	return n
}

# resolve character escapes; fonts kept, \fP resolved; uses font/prev
function esc(s,    out, i, c, d, f, x) {
	out = ""
	for (i = 1; i <= length(s); i++) {
		c = substr(s, i, 1)
		if (c != "\\") { out = out c; continue }
		d = substr(s, i + 1, 1); i++
		if (d == "f") {
			f = substr(s, i + 1, 1); i++
			if (f == "P") f = prev
			if (f != "B" && f != "I") f = "R"
			prev = font; font = f
			out = out "\\f" f
		} else if (d == "-") out = out "-"
		else if (d == "e") out = out "\\\\"
		else if (d == "&") out = out
		else if (d == " ") out = out "\\~"
		else if (d == "(") {
			x = substr(s, i + 1, 2); i += 2
			if (x == "em") out = out "--"
			else if (x == "en") out = out "-"
			else if (x == "bu") out = out "o"
			else if (x == "aq") out = out "'"
			else if (x == "dq") out = out "\""
			else out = out "\\\\(" x
		} else out = out "\\\\" d
	}
	return out
}

# drop redundant font changes; begin and end in roman
function norm(s,    out, cur, pend, i, c, tok) {
	out = ""; cur = "R"; pend = ""
	for (i = 1; i <= length(s); ) {
		c = substr(s, i, 1)
		if (c == "\\" && substr(s, i + 1, 1) == "f") {
			pend = substr(s, i + 2, 1); i += 3; continue
		}
		if (c == "\\") { tok = substr(s, i, 2); i += 2 } else { tok = c; i++ }
		if (pend != "" && pend != cur) { out = out "\\f" pend; cur = pend }
		pend = ""
		out = out tok
	}
	if (cur != "R") out = out "\\fR"
	return out
}

# resolve a request argument or cell, starting and ending in roman
function rtext(s) { font = "R"; prev = "R"; return norm(esc(s)) }

function width(w) { sub(/n$/, "", w); return (w ~ /^[0-9]+$/) ? w + 0 : "" }

function join(a, n, sep,    i, s) {
	s = ""
	for (i = 1; i <= n; i++) s = s (i > 1 ? sep : "") a[i]
	return s
}

# font requests (.B .I .BR ...) to resolved text
function fontreq(name, a, n,    f1, f2, i, s) {
	if (name == "B" || name == "I") return rtext("\\f" name join(a, n, " ") "\\fR")
	f1 = substr(name, 1, 1); f2 = substr(name, 2, 1)
	s = ""
	for (i = 1; i <= n; i++) s = s "\\f" ((i % 2) ? f1 : f2) a[i]
	return rtext(s "\\fR")
}

function isfont(name) { return name ~ /^(B|I|BR|RB|IR|RI|BI|IB)$/ }

# table rows: split on the tab character, open text blocks
function row(s,    i, p, n, piece) {
	while (1) {
		p = index(s, tabc)
		piece = p ? substr(s, 1, p - 1) : s
		if (!p && piece == "T{") { inblock = 1; block = ""; return }
		cells[++nc] = rtext(piece)
		if (!p) break
		s = substr(s, p + 1)
	}
	emitrow()
}

function emitrow(    i, s) {
	s = "tr"
	for (i = 1; i <= nc; i++) s = s TAB cells[i]
	print s
	nc = 0
}

NR == 1 && /^'\\" t/ { next }

intable {
	if (inblock) {
		if (substr($0, 1, 2) == "T}") {
			inblock = 0
			cells[++nc] = rtext(block)
			rest = substr($0, 3)
			if (rest == "") emitrow()
			else row(substr(rest, 2))
		} else block = block (block == "" ? "" : " ") $0
		next
	}
	if ($0 == ".TE") { intable = 0; print "te"; next }
	if (tstate == "opts") {
		line = $0
		tabc = "\t"
		if (match(line, /tab\(.\)/)) {
			tabc = substr(line, RSTART + 4, 1)
			line = substr(line, 1, RSTART - 1) substr(line, RSTART + RLENGTH)
		}
		sub(/;[ ]*$/, "", line)
		gsub(/[ ]+/, " ", line); sub(/^ /, "", line); sub(/ $/, "", line)
		print "ts" TAB line
		tstate = "fmt"; next
	}
	if (tstate == "fmt") {
		line = $0; last = (line ~ /\.[ ]*$/)
		sub(/\.[ ]*$/, "", line)
		n = split(line, k, " ")
		print "tf" TAB join(k, n, TAB)
		if (last) tstate = "data"
		next
	}
	if ($0 == "_") { print "t_"; next }
	nc = 0
	row($0)
	next
}

/^\.\\"/ { next }

/^\./ {
	name = $0; sub(/^\./, "", name); sub(/ .*/, "", name)
	rest = substr($0, length(name) + 2); sub(/^ +/, "", rest)
	n = args(rest, a)
	if (tpwait && isfont(name)) {
		tpwait = 0
		print "tp" TAB tpw TAB fontreq(name, a, n); next
	}
	if (tpwait) { tpwait = 0; print "tp" TAB tpw TAB "" }
	if (name == "TH") {
		for (i = 1; i <= 5; i++) {
			f[i] = (i <= n) ? a[i] : ""
			if (date != "") gsub(/@DATE@/, date, f[i])
			if (version != "") gsub(/@VERSION@/, version, f[i])
			f[i] = rtext(f[i])
		}
		print "th" TAB f[1] TAB f[2] TAB f[3] TAB f[4] TAB f[5]
	}
	else if (name == "SH") print "sh" TAB rtext(join(a, n, " "))
	else if (name == "SS") print "ss" TAB rtext(join(a, n, " "))
	else if (name == "PP" || name == "P" || name == "LP") print "pp"
	else if (name == "TP") { tpwait = 1; tpw = width(a[1]) }
	else if (name == "IP") print "ip" TAB width(a[2]) TAB (n ? rtext(a[1]) : "")
	else if (name == "RS") print "rs" TAB width(a[1])
	else if (name == "RE") print "re"
	else if (name == "nf") { nf = 1; print "nf" }
	else if (name == "fi") { nf = 0; print "fi" }
	else if (name == "sp") print "sp" TAB ((n && a[1] ~ /^[0-9]+$/) ? a[1] + 0 : 1)
	else if (name == "br") print "br"
	else if (name == "TS") { intable = 1; tstate = "opts"; nc = 0 }
	else if (isfont(name)) print "tx" TAB fontreq(name, a, n)
	next
}

{
	if (tpwait) { tpwait = 0; print "tp" TAB tpw TAB rtext($0); next }
	if (!nf && $0 == "") next
	font = "R"
	s = esc((carry != "" ? "\\f" carry : "") $0)
	carry = (font != "R") ? font : ""
	print "tx" TAB norm(s)
}
__ROFFSUB__rs_ir__
# roffsub _rs_ir end
# roffsub _rs_render begin (generated by roffsub-gen.awk; do not edit)
IFS= read -r -d '' _rs_render <<'__ROFFSUB__rs_render__' || :
# roffsub-render.awk --- render roffsub records for a terminal
# roffsub r0.9
# (c) 2026 George Georgalis <george@iuxta.com> Unlimited use with attribution.
#
# usage: awk -v W=80 -v S=plain [-v SB=1] [-v SI=4] [-v M=0] \
#            -f roffsub-render.awk FILE.ir
#
#   W   width in columns
#   S   plain | overstrike | sgr | pre
#       (pre writes \fB \fI \fR markup for the emitter)
#   SB  SGR parameters for bold (default 1)
#   SI  SGR parameters for italic (default 4, underline)
#   M   maximum line length, 0 for none
#   H   section heading column offset, 0 by default
#
# Records arrive on stdin or as a file; never pass them with -v.

BEGIN {
	FS = "\t"
	if (W == "" || W + 0 < 1) W = 80
	W = W + 0
	if (S == "") S = "plain"
	if (SB == "") SB = "1"
	if (SI == "") SI = "4"
	HO = H + 0
	WE = (M + 0 > 0 && M + 0 < W) ? M + 0 : W
	U = (WE < 60) ? 4 : 7
	SSI = int(U / 2)
	NB = "\001"; ESC = "\033"; BS = "\b"
	L = 0; PI = U; TI = 0; TL = 0; rsn = 0
	nfm = 0; started = 0; afterhead = 0
	BC = ""; BA = ""; hastag = 0; TC = ""; TA = ""
	intab = 0; collect = 0
}

function sp(n,    s) { s = ""; while (n-- > 0) s = s " "; return s }
function rep(c, n,    s) { s = ""; while (n-- > 0) s = s c; return s }

# split a record text into chars PC and attributes PA
function parse(s,    i, c, d, f) {
	PC = ""; PA = ""; f = "R"
	for (i = 1; i <= length(s); i++) {
		c = substr(s, i, 1)
		if (c == "\\") {
			d = substr(s, i + 1, 1)
			if (d == "f") { f = substr(s, i + 2, 1); i += 2; continue }
			c = (d == "~") ? NB : d
			i++
		}
		PC = PC c; PA = PA f
	}
}

# attributes promoted by a font (heading bold, table b/i)
function promote(a, f) { if (f == "B" || f == "I") gsub(/R/, f, a); return a }

# write one finished line in the selected style
function emit(c, a,    i, ch, at, cur, o) {
	o = ""; cur = "R"
	for (i = 1; i <= length(c); i++) {
		ch = substr(c, i, 1); at = substr(a, i, 1)
		if (ch == NB) ch = " "
		if (S == "overstrike") {
			if (ch != " " && at == "B") o = o ch BS ch
			else if (ch != " " && at == "I") o = o "_" BS ch
			else o = o ch
			continue
		}
		if (S == "sgr" || S == "pre") {
			if (at != cur) {
				if (S == "sgr") {
					if (cur != "R") o = o ESC "[0m"
					if (at == "B") o = o ESC "[" SB "m"
					else if (at == "I") o = o ESC "[" SI "m"
				} else o = o "\\f" at
				cur = at
			}
			if (S == "pre" && ch == "\\") ch = "\\\\"
		}
		o = o ch
	}
	if (cur != "R") o = o ((S == "sgr") ? ESC "[0m" : "\\fR")
	print o
}

# finish a line: trim trailing blanks, then print or collect
function out(c, a) {
	while (c != "" && substr(c, length(c), 1) == " ") {
		c = substr(c, 1, length(c) - 1); a = substr(a, 1, length(a) - 1)
	}
	if (collect) { LN++; LCC[LN] = c; LCA[LN] = a; return }
	emit(c, a); started = 1; afterhead = 0
}

function blank() { if (!collect) { print ""; started = 1 } }

# words of c/a into WC/WA, split at plain spaces
function words(c, a,    i, ch, n, wc, wa) {
	n = 0; wc = ""; wa = ""
	for (i = 1; i <= length(c); i++) {
		ch = substr(c, i, 1)
		if (ch == " ") {
			if (wc != "") { WC[++n] = wc; WA[n] = wa; wc = ""; wa = "" }
			continue
		}
		wc = wc ch; wa = wa substr(a, i, 1)
	}
	if (wc != "") { WC[++n] = wc; WA[n] = wa }
	return n
}

# greedy fill: first line begins with prefix pc/pa, later lines at ci,
# lines end at column lim
function fill(c, a, pc, pa, ci, lim,    n, i, lc, la, empty) {
	n = words(c, a)
	lc = pc; la = pa; empty = 1
	for (i = 1; i <= n; i++) {
		if (empty) { lc = lc WC[i]; la = la WA[i]; empty = 0 }
		else if (length(lc) + 1 + length(WC[i]) <= lim) {
			lc = lc " " WC[i]; la = la "R" WA[i]
		} else {
			out(lc, la)
			lc = sp(ci) WC[i]; la = rep("R", ci) WA[i]
		}
	}
	if (!empty || lc ~ /[^ ]/) out(lc, la)
}

function vsp() { if (started && !afterhead) blank() }

function flush(    pc, pa) {
	if (BC == "" && !hastag) return
	if (hastag) {
		if (length(TC) < TI - TL) {
			pc = sp(TL) TC sp(TI - TL - length(TC))
			pa = rep("R", TL) TA rep("R", TI - TL - length(TC))
		} else {
			out(sp(TL) TC, rep("R", TL) TA)
			pc = sp(TI); pa = rep("R", TI)
		}
	} else { pc = sp(TI); pa = rep("R", TI) }
	fill(BC, BA, pc, pa, TI, WE)
	BC = ""; BA = ""; hastag = 0
}

function heading(s, ind) {
	flush()
	if (started) blank()
	parse(s)
	out(sp(ind) PC, rep("R", ind) promote(PA, "B"))
	afterhead = 1
	L = U; PI = U; TI = L; TL = L; rsn = 0
}

# ---- tables ----

function key(k, i, j,    al, m) {
	al = "l"
	if (k ~ /r/) al = "r"
	else if (k ~ /c/) al = "c"
	KAL[j, i] = al
	KF[j, i] = (k ~ /b/) ? "B" : ((k ~ /i/) ? "I" : "R")
	KW[j, i] = 0
	if (match(k, /w\([0-9]+n?\)/)) {
		m = substr(k, RSTART + 2, RLENGTH - 3); sub(/n$/, "", m)
		KW[j, i] = m + 0
	}
}

function aligned(c, a, w, al,    pad, l) {
	pad = w - length(c)
	if (pad <= 0) { AC = c; AA = a; return }
	if (al == "r") { AC = sp(pad) c; AA = rep("R", pad) a }
	else if (al == "c") {
		l = int(pad / 2)
		AC = sp(l) c sp(pad - l); AA = rep("R", l) a rep("R", pad - l)
	} else { AC = c sp(pad); AA = a rep("R", pad) }
}

function rule(x0,    i, s) {
	s = sp(x0)
	for (i = 1; i <= NCOL; i++) s = s (i > 1 ? "+" : "") rep("-", CW[i] + 2)
	out(s, rep("R", length(s)))
}

function table(    r, i, j, d, f, n, k, nat, flo, sumn, sumf, A, G, cap,
                   s, rem, prog, ord, t, x0, h, lc, la, cnt, box, allbox,
                   center, lab, first, lw) {
	box = (TOPT ~ /(^| )box( |$)/); allbox = (TOPT ~ /allbox/)
	center = (TOPT ~ /center/)
	NCOL = 0
	for (j = 1; j <= TFN; j++) if (KN[j] > NCOL) NCOL = KN[j]
	for (i = 1; i <= NCOL; i++) { nat[i] = 0; flo[i] = 0 }
	d = 0
	for (r = 1; r <= TRN; r++) {
		if (RT[r] == "_") continue
		d++; f = (d < TFN) ? d : TFN
		for (i = 1; i <= NCOL; i++) {
			parse(RC[r, i])
			CC[r, i] = PC; CA[r, i] = promote(PA, KF[f, i]); CAL[r, i] = KAL[f, i]
			if (length(PC) > nat[i]) nat[i] = length(PC)
			n = words(PC, PA)
			for (k = 1; k <= n; k++) if (length(WC[k]) > flo[i]) flo[i] = length(WC[k])
		}
	}
	for (j = 1; j <= TFN; j++) for (i = 1; i <= NCOL; i++) {
		if (KW[j, i] > flo[i]) flo[i] = KW[j, i]
		if (KW[j, i] > nat[i]) nat[i] = KW[j, i]
	}
	sumn = 0; sumf = 0
	for (i = 1; i <= NCOL; i++) { sumn += nat[i]; sumf += flo[i] }
	G = 3 * (NCOL - 1) + 2
	A = WE - TI - G
	if (sumn <= A) {
		for (i = 1; i <= NCOL; i++) CW[i] = nat[i]
	} else if (sumf > A) {
		records(); return
	} else {
		for (cap = sumn; cap >= 0; cap--) {
			s = 0
			for (i = 1; i <= NCOL; i++) s += mincap(nat[i], flo[i], cap)
			if (s <= A) break
		}
		for (i = 1; i <= NCOL; i++) { CW[i] = mincap(nat[i], flo[i], cap); ord[i] = i }
		for (i = 1; i <= NCOL; i++) for (j = i + 1; j <= NCOL; j++)
			if (nat[ord[j]] > nat[ord[i]]) { t = ord[i]; ord[i] = ord[j]; ord[j] = t }
		rem = A - s
		while (rem > 0) {
			prog = 0
			for (k = 1; k <= NCOL && rem > 0; k++) {
				i = ord[k]
				if (CW[i] < nat[i]) { CW[i]++; rem--; prog = 1 }
			}
			if (!prog) break
		}
	}
	lw = G; for (i = 1; i <= NCOL; i++) lw += CW[i]
	x0 = TI
	if (center && WE - TI > lw) x0 = TI + int((WE - TI - lw) / 2)
	if (box || allbox) rule(x0)
	for (r = 1; r <= TRN; r++) {
		if (RT[r] == "_") { if (!allbox) rule(x0); continue }
		h = 0
		for (i = 1; i <= NCOL; i++) {
			collect = 1; LN = 0
			fill(CC[r, i], CA[r, i], "", "", 0, CW[i])
			collect = 0
			cnt[i] = LN
			for (k = 1; k <= LN; k++) { TLC[i, k] = LCC[k]; TLA[i, k] = LCA[k] }
			if (LN > h) h = LN
		}
		for (k = 1; k <= h; k++) {
			lc = sp(x0); la = rep("R", x0)
			for (i = 1; i <= NCOL; i++) {
				if (k <= cnt[i]) aligned(TLC[i, k], TLA[i, k], CW[i], CAL[r, i])
				else aligned("", "", CW[i], "l")
				lc = lc (i > 1 ? " " : "") " " AC " "
				la = la (i > 1 ? "R" : "") "R" AA "R"
			}
			out(lc, la)
		}
		if (allbox) rule(x0)
	}
	if (box && !allbox) rule(x0)
}

function mincap(n, f, cap,    w) { w = (f > cap) ? f : cap; return (n < w) ? n : w }

# a table too wide for its floors: one "label: value" line per cell
function records(    r, i, first, lab, c, a, nrow) {
	first = 1
	if (TRN >= 2 && RT[1] != "_" && RT[2] == "_") {
		for (i = 1; i <= NCOL; i++) { LABC[i] = CC[1, i]; LABA[i] = CA[1, i] }
		first = 3
	} else for (i = 1; i <= NCOL; i++) { LABC[i] = i ""; LABA[i] = rep("R", length(i "")) }
	nrow = 0
	for (r = first; r <= TRN; r++) {
		if (RT[r] == "_") continue
		if (nrow++) blank()
		for (i = 1; i <= NCOL; i++) {
			c = LABC[i] ": " CC[r, i]; a = LABA[i] "RR" CA[r, i]
			fill(c, a, sp(TI), rep("R", TI), TI + 2, WE)
		}
	}
}

# ---- records ----

$1 == "v" { if ($2 + 0 != 1) { print "roffsub: unsupported record version " $2 > "/dev/stderr"; exit 2 } next }
$1 == "th" { next }
$1 == "sh" { heading($2, HO); next }
$1 == "ss" { heading($2, SSI); next }
$1 == "pp" { flush(); vsp(); PI = U; TI = L; TL = L; next }
$1 == "tp" || $1 == "ip" {
	flush(); vsp()
	if ($2 != "") PI = $2 + 0
	TL = L; TI = L + PI
	hastag = ($1 == "tp" || $3 != "")
	parse($3); TC = PC; TA = PA
	next
}
$1 == "rs" {
	flush(); rsn++; RSL[rsn] = L; RSP[rsn] = PI
	L += ($2 != "") ? $2 + 0 : PI
	PI = U; TI = L; TL = L
	next
}
$1 == "re" {
	flush()
	if (rsn > 0) { L = RSL[rsn]; PI = RSP[rsn]; rsn-- }
	TI = L; TL = L
	next
}
$1 == "nf" { flush(); nfm = 1; next }
$1 == "fi" { flush(); nfm = 0; next }
$1 == "br" { flush(); next }
$1 == "sp" { flush(); n = $2 + 0; while (n-- > 0) blank(); afterhead = 0; next }
$1 == "ts" { flush(); TOPT = $2; TFN = 0; TRN = 0; next }
$1 == "tf" { TFN++; KN[TFN] = NF - 1; for (i = 2; i <= NF; i++) key($i, i - 1, TFN); next }
$1 == "tr" { TRN++; RT[TRN] = "r"; for (i = 2; i <= NF; i++) RC[TRN, i - 1] = $i
	for (; i - 1 <= KN[1]; i++) RC[TRN, i - 1] = ""; next }
$1 == "t_" { TRN++; RT[TRN] = "_"; next }
$1 == "te" { table(); next }
$1 == "tx" {
	parse($2)
	if (nfm) {
		if (hastag) flush()
		out(sp(TI) PC, rep("R", TI) PA)
		next
	}
	if (BC != "") { BC = BC " "; BA = BA "R" }
	BC = BC PC; BA = BA PA
	next
}
END { flush() }
